def sort_versions(vs):
    def version_to_int(v):
        try:
            maj, min, patch = map(int, v.split('.'))
        except (ValueError, IndexError):
            return float('-inf')
        return maj * 1000000 + min * 1000 + patch
    return sorted(filter(lambda x: isinstance(x, str), vs), key=version_to_int)

